<script setup>
import { transportLabel, statusLabel } from '../presentation'
import { onMounted, ref } from 'vue'
import DeviceTwin from './DeviceTwin.vue'
import DeviceShadow from './DeviceShadow.vue'
import { api, formatTime, notifyError, pretty } from '../api'
import { ElMessageBox, ElMessage } from 'element-plus'
import { commandStatuses, alarmType, alarmLevel, alarmStatuses, connectionStatuses, dataStatuses, businessStatuses, stateSources, label } from '../labels'
const props=defineProps({deviceId:String})
const emit=defineEmits(['close','navigate'])
const histories=ref([]),events=ref([]),commands=ref([]),historyTotal=ref(0),historyPage=ref(1),eventTotal=ref(0),eventPage=ref(1),commandTotal=ref(0),commandPage=ref(1),credential=ref(null),commandType=ref(''),commandData=ref('{}'),pendingCommand=ref(null)
const selectedProfile=ref('')
const pendingProtocol=ref(null)
const data=ref(null),busy=ref(false),command=ref('{"type":""}'),commandResult=ref(null)
const base=()=>`/api/v1/device-registry/${encodeURIComponent(props.deviceId)}`
async function loadHistory(){const x=await api(`${base()}/history?page=${historyPage.value}`);histories.value=x.items;historyTotal.value=x.total}
async function loadEvents(){const x=await api(`${base()}/history?kind=event&page=${eventPage.value}`);events.value=x.items;eventTotal.value=x.total}
async function loadCommands(){const x=await api(`${base()}/commands?page=${commandPage.value}`);commands.value=x.items;commandTotal.value=x.total}
async function pageLoad(fn){try{await fn()}catch(e){notifyError(e)}}
async function rotate(){try{await ElMessageBox.confirm('重新生成后旧凭据立即在平台停用；消息服务撤销结果可在下方查看。','重新生成凭据');const x=await api(`${base()}/credentials`,{method:'POST'});credential.value=x.credential;await load()}catch(e){if(e!=='cancel'&&e!=='close')notifyError(e)}}
async function sendMQTT(){busy.value=true;try{await ElMessageBox.confirm('确认向该设备发送此命令？发送成功不代表执行成功。','人工确认命令');const body={type:commandType.value,data:JSON.parse(commandData.value)};const signature=JSON.stringify(body);if(!pendingCommand.value||pendingCommand.value.signature!==signature)pendingCommand.value={signature,id:crypto.randomUUID()};commandResult.value=await api(`${base()}/commands`,{method:'POST',body:JSON.stringify({...body,id:pendingCommand.value.id,confirmed:true})});await loadCommands()}catch(e){if(e!=='cancel'&&e!=='close')notifyError(e)}finally{busy.value=false}}
function newCommand(){pendingCommand.value=null;commandResult.value=null}
async function load(){busy.value=true;try{data.value=await api(`/api/v1/device-registry/${encodeURIComponent(props.deviceId)}/connection${selectedProfile.value ? `?profileId=${encodeURIComponent(selectedProfile.value)}` : ''}`);selectedProfile.value=data.value.profile?.id||'';await Promise.all([loadHistory(),loadEvents(),loadCommands()])}catch(e){if(e!=='cancel'&&e!=='close')notifyError(e)}finally{busy.value=false}}
async function disable(){try{await ElMessageBox.confirm('禁用后设备不能使用此凭据上报或换取消息订阅令牌。','禁用设备凭据');await api(`/api/v1/device-registry/${encodeURIComponent(props.deviceId)}/credentials`,{method:'DELETE'});ElMessage.success('凭据已禁用');await load()}catch(e){if(e!=='cancel'&&e!=='close')notifyError(e)}}
async function send(){busy.value=true;try{await ElMessageBox.confirm('确认向该设备发送协议命令？请核对设备与参数。','人工确认命令');const body=JSON.parse(command.value);const signature=JSON.stringify([data.value.profile.id,props.deviceId,body]);if(!pendingProtocol.value||pendingProtocol.value.signature!==signature)pendingProtocol.value={signature,id:crypto.randomUUID()};commandResult.value=await api(`/api/v2/device-access-profiles/${encodeURIComponent(data.value.profile.id)}/devices/${encodeURIComponent(props.deviceId)}/commands`,{method:'POST',body:JSON.stringify({...body,requestId:pendingProtocol.value.id,confirmed:true})})}catch(e){if(e!=='cancel'&&e!=='close')notifyError(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template>
<el-drawer :model-value="true" title="设备连接与数据" size="min(780px, 96vw)" @close="emit('close')"><div v-loading="busy"><el-button :loading="busy" @click="load">刷新</el-button><template v-if="data"><el-descriptions :column="2" border><el-descriptions-item label="设备">{{data.device.name}}</el-descriptions-item><el-descriptions-item label="产品">{{data.product.name}}</el-descriptions-item><el-descriptions-item label="接入方式">{{transportLabel(data.connector)}}</el-descriptions-item><el-descriptions-item label="创建时间">{{formatTime(data.device.createdAt)}}</el-descriptions-item><el-descriptions-item label="当前绑定协议">{{data.protocolId||'—'}}</el-descriptions-item><el-descriptions-item label="绑定版本">{{data.protocolVersion||'—'}}</el-descriptions-item><el-descriptions-item v-if="data.profile?.collectorId" label="采集器">{{data.profile.collectorId}}</el-descriptions-item><el-descriptions-item label="运行时">{{data.profile?.runtimeStatus ? statusLabel(data.profile.runtimeStatus) : '按上报更新'}}</el-descriptions-item><el-descriptions-item label="最后上报">{{formatTime(data.connection.lastSeenAt)}}</el-descriptions-item><el-descriptions-item label="连接状态">{{label(connectionStatuses,data.connection.connectionStatus)||'未知'}}</el-descriptions-item><el-descriptions-item label="数据状态">{{label(dataStatuses,data.connection.dataStatus)||'未知'}}</el-descriptions-item><el-descriptions-item label="业务状态">{{label(businessStatuses,data.connection.businessStatus)||'未知'}}</el-descriptions-item><el-descriptions-item label="最后连接">{{formatTime(data.connection.lastConnectAt)}}</el-descriptions-item><el-descriptions-item label="最后断开">{{formatTime(data.connection.lastDisconnectAt)}}</el-descriptions-item><el-descriptions-item label="最近错误">{{data.profile?.lastError||'—'}}</el-descriptions-item></el-descriptions><template v-if="data.profiles?.length > 1"><p>检测到多个关联实例，请选择要查看和发送命令的实例。</p><el-select v-model="selectedProfile" placeholder="选择接入实例" @change="load"><el-option v-for="p in data.profiles" :key="p.id" :value="p.id" :label="p.id"/></el-select></template><template v-if="data.accessInfo"><h4>设备接入信息</h4><p>接口：{{data.accessInfo.httpUrl}}</p><p>消息订阅：{{data.accessInfo.mqttBroker||'未配置对外地址'}} · 客户端标识：{{data.accessInfo.clientId}}</p><p>认证用户名 / 接入密钥：{{data.accessInfo.username}}</p><p>上行：{{data.accessInfo.upTopic}}</p><p>下行：{{data.accessInfo.downTopic}}</p></template><p>原文接收：{{data.ingest?.rawReceived?'已收到':'等待上报'}} · 解析：{{data.ingest?.parsed?'已完成':data.ingest?.parseError?'失败':'等待处理'}}</p><p v-if="data.ingest?.parseError">{{data.ingest.parseError}}</p><h4>在线会话</h4><el-table :data="data.sessions" empty-text="暂无已识别的在线会话"><el-table-column prop="profileId" label="接入实例"/><el-table-column prop="remoteAddress" label="远端地址"/><el-table-column prop="protocolId" label="会话协议"/><el-table-column prop="protocolVersion" label="会话版本"/><el-table-column label="最后有效报文"><template #default="{row}">{{formatTime(row.lastSeenAt)}}</template></el-table-column></el-table><h4>连接与状态历史</h4><el-table :data="histories" empty-text="暂无状态变更"><el-table-column label="记录时间"><template #default="{row}">{{formatTime(row.recordedAt)}}</template></el-table-column><el-table-column label="连接"><template #default="{row}">{{label(connectionStatuses,row.state?.connectionStatus)}}</template></el-table-column><el-table-column label="业务"><template #default="{row}">{{label(businessStatuses,row.state?.businessStatus)}}</template></el-table-column><el-table-column label="来源"><template #default="{row}">{{label(stateSources,row.state?.statusSource)}}</template></el-table-column></el-table><el-pagination v-model:current-page="historyPage" :page-size="20" :total="historyTotal" layout="prev, pager, next" @current-change="pageLoad(loadHistory)"/>
<h4>最近事件</h4><pre v-for="event in events" :key="event.messageId">{{formatTime(event.timestamp)}} · {{event.messageId}}
{{pretty(event.event)}}</pre><p v-if="!events.length">暂无事件</p><el-pagination v-model:current-page="eventPage" :page-size="20" :total="eventTotal" layout="prev, pager, next" @current-change="pageLoad(loadEvents)"/>
<el-collapse><el-collapse-item title="设备孪生与拓扑" name="twin"><DeviceTwin :device-id="props.deviceId" /></el-collapse-item><el-collapse-item title="设备影子" name="shadow"><DeviceShadow :device-id="props.deviceId" /></el-collapse-item></el-collapse><h4>最近告警</h4><el-table :data="data.recentAlarms||[]" empty-text="暂无告警"><el-table-column label="告警"><template #default="{row}">{{alarmType(row.alarmType)}}</template></el-table-column><el-table-column label="级别"><template #default="{row}">{{alarmLevel(row.alarmLevel)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{label(alarmStatuses,row.status)}}</template></el-table-column><el-table-column label="最近触发"><template #default="{row}">{{formatTime(row.lastTriggeredAt)}}</template></el-table-column></el-table><h4>最新属性</h4><pre>{{pretty(data.latestProperties?.[0]?.properties||{})}}</pre><h4>最新报文</h4><pre>{{pretty(data.latest)}}</pre><el-button @click="emit('navigate','raw',{deviceId:props.deviceId})">原始报文与回放</el-button><el-button @click="emit('navigate','alarms',{deviceId:props.deviceId})">设备告警</el-button><el-button :disabled="!data.credentialEnabled" @click="disable">禁用凭据</el-button><el-button @click="rotate">重新生成凭据</el-button><pre v-if="credential">仅本次显示，请妥善保存：{{pretty(credential)}}</pre><p v-for="revocation in data.revocations" :key="revocation.id">旧凭据消息服务撤销：{{revocation.status==='REVOKED'?'已完成':'待完成（平台已停用旧凭据）'}}</p>
<template v-if="data.connector==='MQTT'"><h4>设备消息命令</h4><p>已发送不代表设备执行成功。回执到达后刷新可查看结果；重试相同命令不会再次下发。</p><el-select v-if="data.product.thingModel?.commands?.length" v-model="commandType" placeholder="命令类型"><el-option v-for="c in data.product.thingModel.commands" :key="c.identifier" :value="c.identifier" :label="c.name||c.identifier"/></el-select><el-input v-else v-model="commandType" placeholder="命令类型"/><el-input v-model="commandData" type="textarea" :rows="4" placeholder="命令参数结构化数据"/><el-button :disabled="!data.mqttCommandAvailable||!data.credentialEnabled" :loading="busy" @click="sendMQTT">发送设备消息命令</el-button><el-button v-if="pendingCommand" @click="newCommand">开始一条新命令</el-button><p v-if="commandResult?.lastError">{{label(commandStatuses,commandResult.status)}} · {{commandResult.lastError||''}}</p><pre v-if="commandResult">{{pretty(commandResult)}}</pre><el-table :data="commands"><el-table-column prop="type" label="命令"/><el-table-column label="状态"><template #default="{row}">{{label(commandStatuses,row.status)}}</template></el-table-column><el-table-column label="回执"><template #default="{row}">{{pretty(row.reply||{})}}</template></el-table-column></el-table><el-pagination v-model:current-page="commandPage" :page-size="20" :total="commandTotal" layout="prev, pager, next" @current-change="pageLoad(loadCommands)"/></template>
<template v-if="data.sessions.length&&data.profile&&data.canCommand"><h4>协议命令</h4><el-input v-model="command" type="textarea" :rows="4" placeholder="按协议文档填写命令"/><el-button :loading="busy" :disabled="!data.profile.enabled" @click="send">发送命令</el-button><el-button v-if="pendingProtocol" @click="pendingProtocol=null">开始一条新命令</el-button><p v-if="commandResult?.lastError">{{label(commandStatuses,commandResult.status)}} · {{commandResult.lastError||''}}</p><pre v-if="commandResult">{{pretty(commandResult)}}</pre></template></template></div></el-drawer>
</template>
<style scoped>.el-descriptions{margin-top:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--el-fill-color-light);padding:12px}</style>
